using sv_f951f600fb6345d5ac1428086d0ee0f7.Models;

namespace sv_f951f600fb6345d5ac1428086d0ee0f7.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> SeedData = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with San Marzano tomatoes, fresh mozzarella, and basil.", 30),
            new(2, "Spaghetti Carbonara", "Rich Roman pasta with guanciale, egg yolks, Pecorino Romano, and black pepper.", 25),
            new(3, "Tiramisu", "Layered dessert of espresso-soaked ladyfingers and mascarpone cream.", 45),
            new(4, "Risotto alla Milanese", "Creamy saffron-infused Arborio rice finished with butter and Parmigiano.", 40),
        },
        [2] = new List<Recipe>
        {
            new(5, "Kung Pao Chicken", "Spicy stir-fried chicken with peanuts, Sichuan peppercorns, and dried chillies.", 35),
            new(6, "Mapo Tofu", "Silken tofu in a fiery, numbing sauce of doubanjiang, ground pork, and Sichuan pepper.", 20),
            new(7, "Xiaolongbao", "Delicate soup dumplings filled with seasoned pork and rich broth.", 90),
        },
        [3] = new List<Recipe>
        {
            new(8, "Tacos al Pastor", "Spit-roasted pork with pineapple, cilantro, and onion on corn tortillas.", 50),
            new(9, "Guacamole", "Fresh avocado dip with lime, cilantro, jalapeño, and tomato.", 10),
            new(10, "Chiles en Nogada", "Poblano chillies stuffed with picadillo and topped with walnut cream sauce.", 75),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (SeedData.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IDisposable
@using sv_f951f600fb6345d5ac1428086d0ee0f7.Models
@using sv_f951f600fb6345d5ac1428086d0ee0f7.Services
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes — Cuisine @CuisineId</PageTitle>

<h1>Recipes — Cuisine @CuisineId</h1>

@if (_sort is not null)
{
    <p class="text-muted">Sorted by: <strong>@_sort</strong></p>
}

@* Error state *@
@if (_error is not null)
{
    <div class="alert alert-danger d-flex align-items-center justify-content-between" role="alert">
        <span>@_error</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="Retry">Retry</button>
    </div>
}
else
{
    @* Initial loading — no data yet *@
    @if (_recipes is null && _isLoading)
    {
        <div class="d-flex align-items-center gap-2 my-4">
            <div class="spinner-border spinner-border-sm" role="status"></div>
            <span>Loading recipes…</span>
        </div>
    }
    else if (_recipes is not null)
    {
        @* Refreshing indicator when navigating between cuisines *@
        @if (_isLoading)
        {
            <div class="d-flex align-items-center gap-2 mb-3">
                <div class="spinner-border spinner-border-sm" role="status"></div>
                <span class="text-muted">Refreshing…</span>
            </div>
        }

        @if (_recipes.Count == 0)
        {
            <p>No recipes found for this cuisine.</p>
        }
        else
        {
            <div class="row row-cols-1 row-cols-md-2 g-3">
                @foreach (var recipe in DisplayRecipes)
                {
                    <div class="col">
                        <div class="card h-100">
                            <div class="card-body">
                                <h5 class="card-title">@recipe.Title</h5>
                                <p class="card-text">@recipe.Description</p>
                                <span class="badge bg-secondary">@recipe.PrepTimeMinutes min</span>
                            </div>
                        </div>
                    </div>
                }
            </div>
        }
    }
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isLoading;
    private string? _error;
    private string? _sort;
    private int _loadedCuisineId;

    private CancellationTokenSource? _cts;

    private IEnumerable<Recipe> DisplayRecipes =>
        _sort?.Equals("popular", StringComparison.OrdinalIgnoreCase) == true
            ? _recipes!.OrderByDescending(r => r.PrepTimeMinutes)
            : _recipes!.OrderByDescending(r => r.Id);

    public override async Task SetParametersAsync(ParameterView parameters)
    {
        var previousCuisineId = CuisineId;
        await base.SetParametersAsync(parameters);

        _sort = Sort;

        // Only reload when the cuisine changes (not on sort-only changes).
        if (CuisineId != previousCuisineId || (_recipes is null && _error is null && !_isLoading))
        {
            await LoadRecipesAsync();
        }
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request for the previous cuisine.
        await CancelPendingRequestAsync();

        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _error = null;
        _isLoading = true;
        _loadedCuisineId = CuisineId;
        StateHasChanged();

        try
        {
            var recipes = await RecipeService.GetByCuisineAsync(CuisineId, token);

            // Guard against a stale callback after cancellation.
            if (token.IsCancellationRequested)
                return;

            _recipes = recipes;
            _isLoading = false;
        }
        catch (OperationCanceledException)
        {
            // Expected when switching cuisines or disposing — do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _isLoading = false;
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _isLoading = false;
            _error = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            StateHasChanged();
        }
    }

    private async Task Retry()
    {
        await LoadRecipesAsync();
    }

    private async Task CancelPendingRequestAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }
}

